select distinct on(x->>'id') x->>'id' id,x->>'datetime' start,x#>>'{home_team,full_name}' home,x#>>'{visitor_team,full_name}' away,source_received_at at,case when x->>'status'='Final' then jsonb_build_object('homeId',x#>'{home_team,id}','awayId',x#>'{visitor_team,id}','homeScore',x->'home_team_score','awayScore',x->'visitor_team_score','homeQuarters',jsonb_build_array(x->'home_q1',x->'home_q2',x->'home_q3',x->'home_q4'),'awayQuarters',jsonb_build_array(x->'visitor_q1',x->'visitor_q2',x->'visitor_q3',x->'visitor_q4'),'homeOvertime',jsonb_strip_nulls(jsonb_build_object('1',x->'home_ot1','2',x->'home_ot2','3',x->'home_ot3')),'awayOvertime',jsonb_strip_nulls(jsonb_build_object('1',x->'visitor_ot1','2',x->'visitor_ot2','3',x->'visitor_ot3'))) end final from nba_market_schedules_v1 cross join lateral jsonb_array_elements(payload#>'{data,games}') x where coalesce(x->>'postponed','false')='false' and source_received_at >= now()-interval '3 days' order by x->>'id',(x->>'status'='Final') desc,case when x->>'status'='Final' then source_received_at end asc,source_received_at desc
